/** 已经补挂过人格段的 agent id → 挂的那个 ctx（ctx 换过要重挂，同一 ctx 不重复注册）。 [FS-REMOUNT-PATCH] */
const sectionsMounted = new Map();
/** 拿不到 `agent.ctx` 的告警节流（agent id → 上次喊的时间）。 */
let missingCtxAt = null;
function mountSectionsFor(agent) {
	const id = String(agent?.id ?? '');
	// ctx 会被宿主换掉（插件重载），只按 id 记「挂过」会让新 ctx 永远补不上，所以比的是 ctx 本身。
	if (id === '' || (agent?.ctx !== undefined && sectionsMounted.get(id) === agent.ctx)) return;
